-- Conteos de comprobación:
SELECT 'rol' AS tabla, COUNT(*) AS registros FROM rol UNION ALL
SELECT 'usuario', COUNT(*) FROM usuario UNION ALL
SELECT 'sector', COUNT(*) FROM sector UNION ALL
SELECT 'vecino', COUNT(*) FROM vecino UNION ALL
SELECT 'tipo_material', COUNT(*) FROM tipo_material UNION ALL
SELECT 'regla_puntos', COUNT(*) FROM regla_puntos UNION ALL
SELECT 'entrega', COUNT(*) FROM entrega UNION ALL
SELECT 'detalle_entrega', COUNT(*) FROM detalle_entrega UNION ALL
SELECT 'reporte_punto_critico', COUNT(*) FROM reporte_punto_critico UNION ALL
SELECT 'atencion_punto_critico', COUNT(*) FROM atencion_punto_critico UNION ALL
SELECT 'canje', COUNT(*) FROM canje UNION ALL
SELECT 'movimiento_puntos', COUNT(*) FROM movimiento_puntos;
-- Saldo real derivado de movimientos, nunca editable:
SELECT v.id_vecino, u.username, COALESCE(SUM(mp.puntos),0) AS saldo
FROM vecino v JOIN usuario u ON u.id_usuario=v.id_usuario
LEFT JOIN movimiento_puntos mp ON mp.id_vecino=v.id_vecino
GROUP BY v.id_vecino, u.username ORDER BY saldo DESC LIMIT 10;
